/*
Customer Behaviour Analysis
SQL Server 
Prerequisite: load the cleaned dataset into dbo.Customers.
*/
--Total revenue generated by male vs female customers

SELECT SUM(purchase_amount) AS 'Total Revenue',gender
FROM Customers
GROUP BY gender;

--Which Customer used a discount but still spent more than average purchase amount?
SELECT customer_id,gender,purchase_amount,discount_applied
FROM Customers
WHERE purchase_amount>(SELECT AVG(purchase_amount)
                        FROM Customers) AND discount_applied='Yes';

-- Which are the top 5 products with highest average review rating
SELECT TOP (5) item_purchased, ROUND(AVG(review_rating),2) AS 'Average Ratings'
FROM Customers
GROUP BY item_purchased
HAVING AVG(review_rating)>(SELECT AVG(review_rating)
                              FROM Customers)
ORDER BY AVG(review_rating) DESC;

--Compare the average purchase amount between different shipping type
SELECT AVG(purchase_amount) AS 'Average Purchase Amount', shipping_type
FROM Customers
GROUP BY shipping_type;

-- Do subscribed customers spend more.
SELECT SUM(purchase_amount) AS 'Total Revenue',subscription_status,COUNT(customer_id) AS 'Total Customers'
FROM Customers
GROUP BY subscription_status
ORDER BY [Total Revenue] DESC;

--Which 5 products have the highest percentage of purchases with discounts applied
SELECT TOP (5) item_purchased,
    COUNT(CASE WHEN discount_applied = 'Yes' THEN 1 END) * 100.0
        / COUNT(*) AS Discount_Percentage
FROM Customers
GROUP BY item_purchased
ORDER BY Discount_Percentage DESC;

--Segment Customers based on new,loyal,returning based on their previous number of purchases.
SELECT previous_purchases,customer_id,
CASE WHEN previous_purchases<=1 THEN 'New Customer'
     WHEN previous_purchases< 20 THEN 'Returning Customer'
     ELSE 'Loyal Customer' 
     END AS Customer_Category
FROM Customers
ORDER BY previous_purchases DESC;


-- Count of Customers as per Customer_Category
WITH CustomerSegments AS (
    SELECT
        customer_id,
        CASE
            WHEN previous_purchases = 1 THEN 'New Customer'
            WHEN previous_purchases < 20 THEN 'Returning Customer'
            ELSE 'Loyal Customer'
        END AS Customer_Category
    FROM Customers
)
SELECT
    Customer_Category,
    COUNT(customer_id) AS Customer_Count
FROM CustomerSegments
GROUP BY Customer_Category;


--Top 3 most purchased products under each category
SELECT TOP 10 COUNT(purchase_amount) AS No_of_Purchases,item_purchased,category
FROM Customers
GROUP BY item_purchased,category


-- Top 3 most purchased products under each category

WITH Purchases AS(
SELECT category,item_purchased,COUNT(*) AS No_of_Purchases,
ROW_NUMBER() OVER(PARTITION BY Category
             ORDER BY COUNT(*) DESC) AS rn
FROM Customers
GROUP BY category,item_purchased)

SELECT category,item_purchased,No_of_Purchases
FROM Purchases
WHERE rn<=3;

--Are customers who are repeat buyers atleast 5 times are more likely to subscribe.
SELECT COUNT(customer_id) AS Repeat_Customer,SUM(previous_purchases) AS Total_Amount,subscription_status
FROM Customers
WHERE previous_purchases>=5
GROUP BY subscription_status;

--- Revenue Contribution of each age group
SELECT age_group,SUM(purchase_amount) AS Total_Revenue
FROM Customers
GROUP BY age_group
ORDER BY Total_Revenue DESC;
